INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-at46-mammoth', 1, 'NG-AT326 Rail Gun Turret', '1D6x10 M.D. per 60-round burst; the special monster-fighting rounds described for the Gunwolf robot (Northern Gun One) may be loaded instead', 1, '5,000 ft (1,524 m)', 'Each burst counts as one melee attack', '12,000 rounds (200 bursts), fed from an ammo drum inside the APC', NULL, 'A new, heavy three-barrel gatling-style rail gun in the roof turret, turning 360 degrees with a 45 degree up and down arc, worked by its own gunner. Its solid shells are not reduced by energy-reflecting armour or by magic. Anti-armor; anti-aircraft/flyers.'),
  ('ng-at46-mammoth', 2, 'NG-AT126 Laser Turret', '5D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Unlimited', NULL, 'Nose turret with a camera and laser targeting, turning 180 degrees with a 45 degree up and down arc; a dedicated gunner, the pilot or the co-pilot fires it. Anti-personnel and anti-aircraft/flyers; defense.'),
  ('ng-at46-mammoth', 3, 'NG-AT226 Ion Hatch Turrets (2)', '4D6 M.D. per blast', 1, '1,400 ft (427 m)', 'Each blast counts as one melee attack', 'Unlimited', NULL, 'A swivel-mounted ion blaster beside each side troop hatch, turning 90 degrees with a 30 degree up and down arc; usually fired by the co-pilot and the communications officer. Defense and anti-aircraft/flyers; anti-monster and anti-personnel/bandits.'),
  ('ng-at46-mammoth', 4, 'Ram Prow', 'Bump or sideswipe 2D6 M.D.; low-speed ram 4D6 M.D.; high-speed ram at 40+ mph (64+ km) 1D6x10 M.D.', 1, NULL, 'A bump or sideswipe is one attack, a low-speed ram two and a high-speed ram three', NULL, NULL, 'The front bumper clears light barriers, wire, fences and roadblocks and shoves aside power armor, infantry and light vehicles. A high-speed ram has a 01-70% chance to knock down power armor or giant robots of up to 20 tons, which lose initiative and one melee attack. Into a wall or a crowd, damage is 3D6 M.D. per person, and everyone in its path is thrown several yards, losing initiative and 1D6 melee attacks while they recover.'),
  ('ng-hc46-sentinel', 1, 'NG-SI46 Ion Cannon Turret', '5D6 M.D. per shot', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Heavy ion turret on the roof, turning 180 degrees with a 30 degree up and down arc. Anti-armor and anti-monster; defense.'),
  ('ng-hc46-sentinel', 2, 'NG-SL146 Laser Turret', '3D6 M.D. per shot', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Medium laser in the nose, turning 45 degrees with a 30 degree up and down arc; it sits flush with the hood and can lift about 1 ft (0.3 m) for a higher line of fire. Anti-armor and anti-monster; defense.'),
  ('ng-hc46-sentinel', 3, 'Light Rail Gun (alternative to the laser)', '6D6 M.D. per 20-round burst', 1, '3,000 ft (914 m)', NULL, '2,400 rounds (120 bursts)', NULL, 'Sometimes fitted in place of the NG-SL146 laser, in the same nose housing; the rail gun itself has 30 M.D.C. The page gives no rate of fire for it.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-at46-mammoth', 'ng-at26-road-buster', 'ng-hc46-sentinel');
SELECT 'their 39 locations are in' AS assertion, count(*) AS got, 39 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-at46-mammoth', 'ng-at26-road-buster', 'ng-hc46-sentinel');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-at46-mammoth', 'ng-at26-road-buster', 'ng-hc46-sentinel');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-at46-mammoth', 'ng-at26-road-buster', 'ng-hc46-sentinel') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

